"""Close V02 evidence only after native qualification/application checks succeed."""
from pathlib import Path
import hashlib,json,re,subprocess
from adapter.planner import codec as c,model as m,installation as i
from adapter.tests import qualify_validation_v02 as q
R=q.R;D=q.D;O=q.O

def load(name):return c.parse_json((O/name).read_bytes())

def run():
 generic=load('sealed/generic-qualification.json');app=load('p04-application.json');pre=load('p04-preflights.json');auth=load('authorization.json');cold=load('p04-terminated-writer-readers.json')
 assert generic['RESULT']==app['RESULT']==cold['result']=='PASS'
 assert generic['runtime_hashes']==q.hashes() and generic['writer_terminated_before_reads'] and cold['writer_terminated_before_reads']
 assert all(pre['A09_oracle_terms'].values()) and all(pre['A10_oracle_terms'].values())
 log=(O/'sealed/regressions.log').read_text();assert log.rstrip().endswith('OK');count=int(re.search(r'Ran (\d+) tests',log).group(1))
 baseline=load('baseline.json');changes=[p for p,h in baseline.items() if not (R/p).exists() or hashlib.sha256((R/p).read_bytes()).hexdigest()!=h]
 prior=[p for p in changes if not p.startswith('adapter/planner/')];assert not prior,prior
 assert subprocess.run(['git','diff','--check'],cwd=R,capture_output=True).returncode==0
 bundle=c.restore(D/'DETERMINISTIC_PLANNER_V0_1_E2_P04_POST_A10_INSTALL_BUNDLE_1.json',c._unwire(app['bundle_id']),R)
 assert len(bundle.events)==6 and type(bundle.events[-1].result) is m.InstallDefinition
 assert not bundle.current.validation_results and not bundle.current.validation_support_records and not bundle.current.receipt_admissions and not bundle.current.typed_proofs
 record=next(r for r in bundle.current.installed_definitions if r.id==i.installed_id(bundle.events[-1].result));assert i.current(bundle,record)
 dag={
 'A11':{'capability':'E04 native named reentry/C03 available','readiness':'UNQUALIFIED_BOUNDARY_ORACLE_AND_CURRENTNESS','instances':'Not yet expected: actual accepted A10 receipt/result/support and ReentryEvaluation','required_work':'Qualify exact post-A10 named reentry/C03 boundary against this lineage; no independently ready A11 claim made'},
 'A12':{'readiness':'AUTHORITY_REQUIRED_AND_TYPED_ACTION_ADAPTER_REQUIRED','contracts':'E2-REENTER accepted result inventory is still empty; prospectively install authorized PASS + E2-K-REENTER declaration through typed Action replacement','instances':'ActionResult and actual knowledge must be created only by canonical execution'},
 'A13_ROOT_SLOT':{'readiness':'AUTHORITY_REQUIRED_AND_TYPED_DEFINITION_ADAPTER_REQUIRED','contracts':'Root/slot and distinct SLOT_PROOF/ROOT_PROOF contracts not installed; preserve operating fixture authority separately from INSTALL','instances':'SLOT_PROOF and ROOT_PROOF not yet expected'},
 'A13_FINISH':{'readiness':'AUTHORITY_REQUIRED_AND_TYPED_ACTION_ADAPTER_REQUIRED','contracts':'E2-FINISH accepted inventory remains empty; canonical A13 includes selected finishing result, not readiness alone','instances':'FINISH result absent; no FINISH execution'},
 'REEVALUATION':{'capability':'E06 generic bounded reevaluation available','state_effect':'NONE in this configuration-only package'}}
 q.emit('remaining-continuation-dag.json',dag)
 report={'WORK_PACKAGE':'VALIDATION-V02','RESULT':'PASS','SELECTED_OPTION':'AUTHORIZE_P04_A10_VALIDATION_INSTALLATION','AUTHORIZATION_AUTHENTICATION':'PASS','A10_VALIDATION_SUPPORT_CAPABILITY':'PASS','VALIDATION_RESULT_MODEL':'PASS: typed deterministic parent/receipt/Evidence/contract/assessment/context-bound record','SUPPORT_MODEL':'PASS: closed ACCEPTED_RECEIPT_SUPPORT / REJECTED_RECEIPT_OBSERVATION enum, separate from result and proof','A10_EVENT_TRANSACTION':'PASS: ordinary ValidationSupportAdmission; one atomic event/bundle/HEAD','ATOMICITY':'PASS','IDEMPOTENCE':'PASS','NEGATIVE_TESTS':'PASS','PERSISTENCE':'PASS','COLD_RESTORE':'PASS','REPLAY':'PASS; historical witness verification, zero semantic-validator decisions','DETERMINISM':'PASS','INSTALLATION_ADAPTER':'PASS: one atomic validation/support/transaction definition set','INSTALL_AUTHORITY_ID':app['authority_id'],'INSTALL_AUTHORITY_ADMISSION':'PASS','INSTALL_AUTHORITY_APPLICABILITY':'PASS','P04_VALIDATION_DEFINITION_ID':app['definition_ids']['validation'],'P04_SUPPORT_DEFINITION_ID':app['definition_ids']['support'],'P04_A10_TRANSACTION_DEFINITION_ID':app['definition_ids']['transaction'],'P04_A10_FINAL_INSTALL_EVENT_ID':app['append_head'],'POST_A10_INSTALL_STATE_ID':app['state_id'],'POST_A10_INSTALL_APPEND_HEAD':app['append_head'],'POST_A10_INSTALL_BUNDLE_ID':app['bundle_id'],'OLD_A09_CANDIDATES':'STALE','A09_CANDIDATE_REMATERIALIZED':'YES','FINAL_A09_PREFLIGHT':'PASS; 18/18 independent oracle terms','A09_READY':'YES','A10_EXECUTION_PREFLIGHT':'PASS; simulated received-only lineage','A10_POSTCONDITION_ORACLE':'PASS; 18/18 checks, ACCEPTED/current support, no proof/reentry/completion','A10_READY':'YES','REMAINING_CONTINUATION_DAG':dag,'NEXT_PACKAGE':'A11 exact named reentry/C03 boundary/currentness qualification; then bounded A12/A13 definition installation','P04_EXECUTION_READY':'NO','E2_P04_READY':'NO','A09_A10_EXECUTED':'NO','A09_A13_EXECUTED':'NO','VALIDATION_RESULT_CREATED':'NO_IN_CANONICAL_P04','SUPPORT_INSTANCE_CREATED':'NO_IN_CANONICAL_P04','A11_PROOF_CREATED':'NO','E2_FINISH_EXECUTED':'NO','P03_RESULT':'PASS','P03_HISTORICAL_CORRESPONDENCE':'UNPROVEN','N_REAL_SATISFIED':'NO','CANONICAL_E2_QUALIFIED':'NO','E1_ARTIFACTS_MODIFIED':0,'PRODUCTION_EFFECT':'NO','git_diff_check':'PASS','TARGETED_REGRESSIONS':{'V02_tests':generic['tests_run'],'current_runtime_regressions':count,'total_tests':generic['tests_run']+count,'result':'PASS'},'FRESH_READER_COMPARISONS':{'generic':generic['fresh_reader_comparisons'],'P04_post_install':cold['comparisons'],'total':generic['fresh_reader_comparisons']+cold['comparisons'],'seeds':[0,1,7,101],'readers_per_seed_per_checkpoint':3,'writer_terminated':True,'result':'PASS'},'BROAD_REGRESSION_STATUS':'OTHER: current Python lacks pytest; known pre-existing frozen-E1 duplicate-import collection issue remains separately recorded, no broad-suite PASS claimed','PRESERVATION':{'prior_evidence_changed':prior,'baseline_files_checked':len(baseline),'runtime_files_changed':changes,'route_predicate_source_unchanged':str(R/'adapter/planner/gates.py') not in prior and hashlib.sha256((R/'adapter/planner/gates.py').read_bytes()).hexdigest()==baseline['adapter/planner/gates.py']},'evidence':{'authorization':'qualification/VALIDATION_V02_1/authorization.json','generic':'qualification/VALIDATION_V02_1/sealed/generic-qualification.json','regressions':'qualification/VALIDATION_V02_1/sealed/regressions.log','install_event':'qualification/VALIDATION_V02_1/p04-install-event.json','old_candidates':'qualification/VALIDATION_V02_1/old-candidate-checks.json','preflights':'qualification/VALIDATION_V02_1/p04-preflights.json','cold_readers':'qualification/VALIDATION_V02_1/p04-terminated-writer-readers.json','bundle':'DETERMINISTIC_PLANNER_V0_1_E2_P04_POST_A10_INSTALL_BUNDLE_1.json'},'runtime_hashes':generic['runtime_hashes']}
 target=D/'DETERMINISTIC_PLANNER_V0_1_VALIDATION_V02_RESULT.json';target.write_bytes(c.canonical_bytes(report));q.emit('preservation.json',report['PRESERVATION'])
 md='''# VALIDATION-V02 — native A10 validation/support and authorized installation

RESULT = PASS. A09_READY = YES. A10_READY = YES. P04_EXECUTION_READY = NO.

The exact `AUTHORIZE_P04_A10_VALIDATION_INSTALLATION` decision was authenticated against the unchanged sealed V01 contract. One bounded, single-use INSTALL grant installed the three prospective definitions atomically at event 6 of the qualified I04 lineage. It authorizes configuration only; no operating ATTEST permission, Evidence receipt, validation, support, proof or Action execution is granted by installation.

The generic runtime now has typed validation/support definitions, a closed assessment witness, deterministic ValidationResult and support records, and an ordinary parent-bound ValidationSupportAdmission event. Live preparation runs the registered independent validator on the actual authenticated receipt and pinned semantic source. Acceptance privately projects validation, independently prechecks native receipt clauses, stages exact support, and invokes the existing receipt transition once. Rejection persists a FAIL decision and rejected observation, returns the native gate to waiting, and produces no usable support. Native obligation PROVED is a derived query; no typed proof instance is admitted. Registered gates reject the plain validation-event bypass and public model admission requires the exact result/support projection rather than a proposition-only validation shortcut.

Result, support, event and bundle are staged together under the existing single-writer CAS/fsync/atomic HEAD protocol. Historical replay verifies recorded witness bindings and native postconditions without invoking the live validator. Source withdrawal retains immutable historical outcomes while removing current Evidence/support qualification. The installation adapter accepts only canonical member bytes and the sealed source witnesses, validates the member DAG, and publishes all three definitions together without lifecycle instances. Optional model fields omit empty defaults, preserving prior snapshot/bundle identities. Replay prefix checks hash the already admitted prefix without recursively replaying it; live commit still performs full ledger and source validation.

## Qualification

'''
 md+=f"{generic['tests_run']} V02 tests and {count} affected current-runtime regressions passed ({generic['tests_run']+count} total). The regressions cover I02/I04, E07 atomic ingress, A09 receipt postconditions, typed root/slot proof and Action reevaluation, E01–E05/T01, and G01–G04. Generic PASS and independently sealed semantic FAIL fixtures use TEST identities, not E2 runtime branches. Negatives cover receipt/binding/contract/context/parent/provenance substitution, unsupported operands, plain-event bypass, altered assessment/outcome/support, malformed definition sets, wrong INSTALL permission, stale candidates, expiry and withdrawal. Failure injections leave no reachable partial HEAD; exact retries and independent reproductions preserve native identities, and conflicting retries fail closed.\n\n"
 md+=f"{report['FRESH_READER_COMPARISONS']['total']} final fresh-reader comparisons passed: 72 across accepted/rejected installed, received and validated checkpoints, plus 12 for canonical P04 configuration. Each uses seeds 0, 1, 7 and 101 with three readers per seed/checkpoint, after the writer exits. Readers compare full computation, canonical identities, native-declared unordered source sets, ordered event ancestry and currentness, with the semantic validator forbidden. A preliminary export omission was detected by native restore: event sidecars were missing beside the bundle. Native `save_bundle` emitted the existing ledger artifacts without changing state/event/bundle identities. No runtime relaxation was used.\n\n"
 md+='Broad-suite status is separate: the current Python cannot import pytest. The previously recorded frozen-E1 duplicate-import collection blocker remains unchanged; this package makes no broad-suite PASS claim.\n\n## Authorized P04 configuration\n\n'
 for key in ('INSTALL_AUTHORITY_ID','P04_VALIDATION_DEFINITION_ID','P04_SUPPORT_DEFINITION_ID','P04_A10_TRANSACTION_DEFINITION_ID','POST_A10_INSTALL_STATE_ID','POST_A10_INSTALL_APPEND_HEAD','POST_A10_INSTALL_BUNDLE_ID'):
  md+=f"{key} = `{report[key]['namespace']}:{report[key]['sha256']}`\n\n"
 md+='The published [post-install bundle](DETERMINISTIC_PLANNER_V0_1_E2_P04_POST_A10_INSTALL_BUNDLE_1.json) cold-restores and replays with exact member/content identities, authority, source/policy pins, scope, lineage, generation and event ancestry. Its pre-install prefix is byte-identical to I04; definitions are absent before event 6. Independent installation and exact retry produce the same bundle with no duplicate event or grant use. Native collections are resolved by installed identity/role, never presentation position.\n\n'
 md+='All three archived P04 A09 candidates retain obsolete parent/pre-state bindings. Qualification-only E07 operand wrappers preserve those old bindings and expose native PARENT_MISMATCH; archive bytes are unchanged. The new candidate binds the installed bundle, state and append head and reconstructs the transient E02 operand. Complete A09 precommit passes all 18 independent received-only terms. Against its private simulation, A10 passes all 18 checks: actual Evidence/receipt, current definitions, exact parent/source/context, ACCEPTED validation/current support, unchanged Action completion/knowledge/root/slot, no proof or reentry, and derived EXTERNAL_WAIT. Neither transaction is committed. The private precommit artifact is simulation evidence, not a canonical P04 lifecycle output.\n\n'
 md+='## Remaining boundary and preservation\n\nA11 still needs independent qualification of the exact named reentry/C03 boundary and currentness. A12 has no canonical accepted REENTER result inventory; A13 still needs root/slot/proof and FINISH result definitions through their own typed installation paths and bounded authorities. Those prior route/ATTEST/A10 permissions are not broadened. The actual lifecycle instances belong to future canonical execution. Full P04 readiness remains NO.\n\nP03_RESULT = PASS; historical correspondence = UNPROVEN; N_REAL_SATISFIED = NO; aggregate release gates unchanged. A09–A13 and FINISH executed = NO. Canonical P04 contains no Evidence receipt, ValidationResult, support instance or A11 proof. All prior qualification artifacts and frozen E1 hashes are unchanged. E1_ARTIFACTS_MODIFIED = 0; PRODUCTION_EFFECT = NO; git diff --check = PASS.\n\nExact machine-readable report and evidence links are in [the companion](DETERMINISTIC_PLANNER_V0_1_VALIDATION_V02_RESULT.json). Development/intermediate reader logs are not acceptance evidence; the accepted qualification uses `qualification/VALIDATION_V02_1/sealed/`.\n'
 (D/'DETERMINISTIC_PLANNER_V0_1_VALIDATION_V02_RESULT.md').write_text(md)
 print(json.dumps({'RESULT':'PASS','tests':report['TARGETED_REGRESSIONS']['total_tests'],'readers':report['FRESH_READER_COMPARISONS']['total'],'A09_READY':'YES','A10_READY':'YES','P04_EXECUTION_READY':'NO'}))
if __name__=='__main__':run()
